import re

def json_pointer(doc, pointer: str):
    if pointer == '':
        return doc
    if not pointer.startswith('/'):
        raise ValueError(f"Invalid JSON pointer: {pointer!r} must start with '/'")

    segments = pointer.split('/')[1:]
    current = doc

    for raw_seg in segments:
        # RFC 6901 decoding: '~1' -> '/' must be decoded before '~0' -> '~'
        seg = raw_seg.replace('~1', '/').replace('~0', '~')

        if isinstance(current, dict):
            if seg not in current:
                raise ValueError(f"Key {seg!r} not found in dict")
            current = current[seg]
        elif isinstance(current, list):
            if not re.fullmatch(r'\d+', seg):
                raise ValueError(f"Invalid list index: {seg!r}")
            idx = int(seg)
            if idx < 0 or idx >= len(current):
                raise ValueError(f"List index out of range: {idx}")
            current = current[idx]
        else:
            raise ValueError(
                f"Cannot index into non-dict/non-list value with segment {seg!r}"
            )

    return current
